-- Rollback for iso-46001-md-verification-pack.sql (run 2026-09-08).
-- Reverts ONLY the rows that pack touched — identified both by explicit id list AND by the verification_note
-- tag — and ONLY for standard ISO-46001, joined through worksheet_templates -> standards.code so no other
-- standard can be reached. The 2026-09-08 prod export showed all 97 fields and all 4 equations carrying the
-- single prior status 'imported_unverified' with verification_quote, verification_note and verified_at all
-- null, so every row returns to exactly that prior state.
-- Gates were NOT touched by the pack; the STAGED file was never applied; the encode-time source_quote column
-- is a different column and is left untouched.
-- No transaction control in this file: apply-pack.mjs supplies BEGIN/COMMIT and implements --dry-run by
-- rolling back. An inline commit would silently turn a dry run into a real apply.

-- ---- fields: 97 rows — prior status = imported_unverified ----
update public.fields f set verification_status='imported_unverified', verification_quote=null, verification_note=null, verified_at=null
  from public.worksheet_templates wt join public.standards s on s.id = wt.standard_id
 where wt.id = f.worksheet_template_id and s.code = 'ISO-46001'
