-- ---- equations: 4 rows — prior status = imported_unverified ----
update public.equations e set verification_status='imported_unverified', verification_quote=null, verification_note=null, verified_at=null
  from public.worksheet_templates wt join public.standards s on s.id = wt.standard_id
 where wt.id = e.worksheet_template_id and s.code = 'ISO-46001'
   and e.id in ('bf60d386-4a0c-4270-a506-c923cbf074bd','0cc90c9a-08fe-4816-9fa9-f2c9f80752f7','eeb0aca8-e669-43fc-9c5a-291b54b4eb45','0b1026ab-9a89-4424-b9de-4ec01e6de1af')
